servers.onUp:
function onUp() {
  let s = loadState();
  if (!s.term) {
    s = {
      role: 'follower', term: 0, votedFor: null,
      votes: 0, heartbeat: -1, hbSent: 0,
      timeout: 10 + serverId * 4,
      leader: null, commitIdx: 0,
      log: []
    };
  } else {
    s.role = 'follower';
    s.votedFor = null;
    s.votes = 0;
    s.heartbeat = -1;
  }
  dumpState(s);
}

servers.onTimer:
function onTimer(tick) {
  let s = loadState();
  s.tick = tick;
  if (s.heartbeat < 0) s.heartbeat = tick;

  if (s.role === 'leader') {
    if (tick - s.hbSent >= 5) {
      for (const id of allServerIds) {
        if (id !== serverId) {
          sendMessage(id, {
            type: 'append', term: s.term,
            leader: serverId, ci: s.commitIdx,
            entries: s.log.slice(s.commitIdx)
          });
        }
      }
      s.hbSent = tick;
    }
  } else {
    if (tick - s.heartbeat >= s.timeout) {
      s.role = 'candidate';
      s.term++;
      s.votedFor = serverId;
      s.votes = 1;
      s.heartbeat = tick;
      for (const id of allServerIds) {
        if (id !== serverId) {
          sendMessage(id, {
            type: 'reqVote', term: s.term,
            cand: serverId, logLen: s.log.length
          });
        }
      }
    }
  }
  dumpState(s);
}

servers.onMessage:
function onMessage(message) {
  let s = loadState();
  const m = message.payload;

  if (m.term > s.term) {
    s.term = m.term;
    s.role = 'follower';
    s.votedFor = null;
    s.votes = 0;
  }

  if (m.type === 'reqVote') {
    let ok = false;
    if (m.term >= s.term && (s.votedFor === null || s.votedFor === m.cand)) {
      if (m.logLen >= s.log.length) {
        ok = true;
        s.votedFor = m.cand;
        s.heartbeat = s.tick;
      }
    }
    sendMessage(message.from, { type: 'vote', term: s.term, ok: ok });
  }

  if (m.type === 'vote' && s.role === 'candidate' && m.term === s.term && m.ok) {
    s.votes++;
    const majority = Math.floor(allServerIds.length / 2) + 1;
    if (s.votes >= majority) {
      s.role = 'leader';
      s.leader = serverId;
      s.hbSent = 0;
    }
  }

  if (m.type === 'append') {
    if (m.term >= s.term) {
      s.role = 'follower';
      s.leader = m.leader;
      s.heartbeat = s.tick;
      if (m.entries && m.entries.length > 0) {
        for (const e of m.entries) {
          if (s.log.length < m.ci + m.entries.length) s.log.push(e);
        }
      }
      s.commitIdx = Math.min(m.ci, s.log.length);
      sendMessage(message.from, { type: 'appendOk', term: s.term, ok: true });
    }
  }

  dumpState(s);
}
